UPDATE promotion_capi_event_outbox
SET status = #{pendingStatus},
    event_time = #{eventTime},
    next_retry_at = 0,
    updated_at = #{now}
WHERE pairing_session_id = #{pairingSessionId}
  AND event_stage = #{eventStage}
  AND status = #{waitingStatus}

UPDATE promotion_capi_event_outbox
SET status = #{canceledStatus},
    ,
    updated_at = #{now}
WHERE pairing_session_id = #{pairingSessionId}
  AND status = #{waitingStatus}

