UPDATE promotion_capi_event_outbox
SET status = #{sentStatus}, sent_at = #{sentAt},
    locked_by = NULL, locked_at = NULL,
    last_error_code = NULL, last_error_message = NULL,
    ,
    updated_at = #{sentAt}
WHERE id = #{row.id} AND status = #{lockedStatus}
  AND locked_by = #{row.lockedBy} AND locked_at = #{row.lockedAt}

UPDATE promotion_capi_event_outbox
SET status = #{pendingStatus}, retry_count = retry_count + 1,
    next_retry_at = #{nextRetryAt}, locked_by = NULL, locked_at = NULL,
    last_error_code = #{errorCode}, last_error_message = #{errorMessage},
    updated_at = #{now}
WHERE id = #{row.id} AND status = #{lockedStatus}
  AND locked_by = #{row.lockedBy} AND locked_at = #{row.lockedAt}

UPDATE promotion_capi_event_outbox
SET status = #{deadStatus}, locked_by = NULL, locked_at = NULL,
    last_error_code = #{errorCode}, last_error_message = #{errorMessage},
    ,
    updated_at = #{now}
WHERE id = #{row.id} AND status = #{lockedStatus}
  AND locked_by = #{row.lockedBy} AND locked_at = #{row.lockedAt}

UPDATE promotion_capi_event_outbox
SET status = #{pendingStatus}, locked_by = NULL, locked_at = NULL,
    next_retry_at = #{now}, last_error_code = 'LOCK_EXPIRED',
    last_error_message = 'dispatcher lock expired', updated_at = #{now}
WHERE status = #{lockedStatus}
  AND locked_at IS NOT NULL AND locked_at < #{lockedBefore}
ORDER BY locked_at ASC, id ASC
LIMIT #{limit}

UPDATE promotion_capi_event_outbox
SET status = CASE
      WHEN status = #{waitingStatus} THEN #{canceledStatus}
      ELSE #{deadStatus}
    END,
    locked_by = NULL, locked_at = NULL,
    last_error_code = 'PRIVACY_RETENTION_EXPIRED',
    last_error_message = 'sensitive attribution retention expired',
    ,
    updated_at = #{now}
WHERE sensitive_expires_at <= #{now}
  AND phone_sha256 IS NOT NULL
  AND (
    status IN (#{waitingStatus}, #{pendingStatus})
    OR (status = #{lockedStatus} AND locked_at < #{lockedBefore})
  )
ORDER BY sensitive_expires_at ASC, id ASC
LIMIT #{limit}
